from interfaces.sink import Sink


class Pump:
    """Pulls events from a reader and hands them to its sink."""

    def __init__(self, sink: Sink):
        self.sink = sink

    def run(self, events):
        for event in events:
            self.sink.emit(event)


def flush(sink: Sink, event):
    sink.emit(event)

